(function () {
"use strict";
var body = document.body;
var header = document.getElementById('header');
var scrollTopBtn = document.querySelector('.scroll-top');
var toggleBtn = document.querySelector('.mobile-nav-toggle');
var sticky = !!header && ['scroll-up-sticky', 'sticky-top', 'fixed-top'].some(function (c) {
return header.classList.contains(c);
});
var spy = Array.prototype.slice.call(document.querySelectorAll('.navmenu a'))
.filter(function (a) { return a.hash.length > 1; })
.map(function (a) { return { link: a, section: document.getElementById(a.hash.slice(1)) }; })
.filter(function (i) { return i.section; });
function update() {
var y = window.scrollY;
if (sticky) body.classList.toggle('scrolled', y > 100);
if (scrollTopBtn) scrollTopBtn.classList.toggle('active', y > 100);
var pos = y + 200, current = null;
if (window.innerHeight + y >= document.documentElement.scrollHeight - 2) {
current = spy[spy.length - 1];
} else {
spy.forEach(function (i) {
if (i.section.getBoundingClientRect().top + y <= pos) current = i;
});
}
spy.forEach(function (i) {
var on = i === current;
i.link.classList.toggle('active', on);
if (on) i.link.setAttribute('aria-current', 'true');
else i.link.removeAttribute('aria-current');
});
}
var ticking = false;
window.addEventListener('scroll', function () {
if (ticking) return;
ticking = true;
requestAnimationFrame(function () { update(); ticking = false; });
}, { passive: true });
window.addEventListener('load', update);
window.addEventListener('resize', update);
update();
if (scrollTopBtn) {
scrollTopBtn.addEventListener('click', function (e) {
e.preventDefault();
window.scrollTo({ top: 0, behavior: 'smooth' });
});
}
function setNav(open) {
body.classList.toggle('mobile-nav-active', open);
if (!toggleBtn) return;
toggleBtn.classList.toggle('bi-list', !open);
toggleBtn.classList.toggle('bi-x', open);
toggleBtn.setAttribute('aria-expanded', String(open));
}
if (toggleBtn) {
toggleBtn.addEventListener('click', function () {
setNav(!body.classList.contains('mobile-nav-active'));
});
toggleBtn.addEventListener('keydown', function (e) {
if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleBtn.click(); }
});
}
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') setNav(false);
});
document.addEventListener('click', function (e) {
if (e.target.closest('#navmenu a') && body.classList.contains('mobile-nav-active')) setNav(false);
var t = e.target.closest('.faq-item h3, .faq-item .faq-toggle');
if (t) t.closest('.faq-item').classList.toggle('faq-active');
});
window.addEventListener('load', function () {
if (typeof AOS === 'undefined') return;
AOS.init({
duration: 600,
easing: 'ease-in-out',
once: true,
disable: window.matchMedia('(prefers-reduced-motion: reduce)').matches
});
document.documentElement.classList.add('aos-on');
});
window.addEventListener('load', function () {
var h = window.location.hash;
if (h.length < 2) return;
var el = document.getElementById(decodeURIComponent(h.slice(1)));
if (el) setTimeout(function () { el.scrollIntoView({ behavior: 'smooth' }); }, 100);
});
})();
